#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll pairingCost(const vector<ll>& v) {
    ll cost = 0;
    for (size_t i = 0; i < v.size(); i += 2) {
        cost += v[i + 1] - v[i];
    }
    return cost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> w(2 * n);
    for (ll& x : w) cin >> x;
    sort(w.begin(), w.end());

    ll ans = LLONG_MAX;

    for (int i = 0; i < 2 * n; ++i) {
        for (int j = i + 1; j < 2 * n; ++j) {
            vector<ll> remaining;
            remaining.reserve(2 * n - 2);

            for (int k = 0; k < 2 * n; ++k) {
                if (k != i && k != j) {
                    remaining.push_back(w[k]);
                }
            }

            ans = min(ans, pairingCost(remaining));
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
