using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> w(2 * n);
    for (ll& x : w) cin >> x;
    sort(w.begin(), w.end());

    ll answer = LLONG_MAX;

    for (int i = 0; i < 2 * n; ++i) {
        for (int j = i + 1; j < 2 * n; ++j) {
            ll cost = 0;
            ll previous = 0;
            bool hasPrevious = false;

            for (int k = 0; k < 2 * n; ++k) {
                if (k == i || k == j) continue;

                if (!hasPrevious) {
                    previous = w[k];
                } else {
                    cost += w[k] - previous;
                }
                hasPrevious = !hasPrevious;
            }

            answer = min(answer, cost);
        }
    }

    cout << answer << '\n';
    return 0;
}

